import React from 'react';
import DataTable, {
  Table,
  TableBatchActions,
  TableBatchAction,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableHeader,
  TableRow,
  TableSelectAll,
  TableSelectRow,
  TableToolbar,
  TableToolbarContent,
} from '@carbon/react';

const rows = [
  { id: 'a', name: 'Load balancer 1', status: 'Disabled' },
  { id: 'b', name: 'Load balancer 2', status: 'Starting' },
  { id: 'c', name: 'Load balancer 3', status: 'Active' },
];

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

const MyDataTable = () => {
  return (
    <DataTable rows={rows} headers={headers}>
      {({
        rows,
        headers,
        getHeaderProps,
        getSelectionProps,
        getBatchActionProps,
        getRowProps,
        selectedRows,
        getTableProps,
        getTableContainerProps,
      }) => (
        <TableContainer title="DataTable" description="With Select All">
          <TableToolbar>
            <TableBatchActions {...getBatchActionProps()}>
              <TableBatchAction
                onClick={() => console.log('Select all across pages')}
              >
                Select all
              </TableBatchAction>
            </TableBatchActions>
            <TableToolbarContent>
              <span>{selectedRows.length} items selected</span>
            </TableToolbarContent>
          </TableToolbar>
          <Table {...getTableProps()}>
            <TableHead>
              <TableRow>
                <TableSelectAll {...getSelectionProps()} />
                {headers.map((header) => (
                  <TableHeader {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <TableRow key={row.id} {...getRowProps({ row })}>
                  <TableSelectRow {...getSelectionProps({ row })} />
                  {row.cells.map((cell) => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </DataTable>
  );
};

export default MyDataTable;
